import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { describe, expect, it } from 'vitest';
import { mediaCondition } from '../../breakpoints';
import {
  animatedValue,
  CONSUMERS,
  createHandoff,
  keyframes,
  LIVE_ATTR,
  liveNext,
  originalValue,
  pointerNoneFromEntry,
  sentinelTop,
  threadedLive,
  type ConsumerName,
  type HandoffDeps,
  type Splash,
} from './threaded';

/** Lean golden `hero-exit.threaded.jsonl` (generated by `lean/scripts/ExitThreadedGolden.lean`). */
interface Row {
  fn: string;
  in: Record<string, unknown>;
  out: unknown;
}
const rows: Row[] = readFileSync(resolve(__dirname, '../../../../../packages/contracts/golden/parts/hero-exit.threaded.jsonl'), 'utf8')
  .trim()
  .split('\n')
  .map((l) => JSON.parse(l) as Row);
const q = (r: unknown): number => {
  const o = r as { num: string; den: string };
  return Number(o.num) / Number(o.den);
};
const of = (fn: string) => rows.filter((r) => r.fn === fn);

describe('hero.exit:threaded against the Lean golden', () => {
  it('has every kind of row', () => {
    expect(of('keyframes').length).toBe(14);
    expect(of('anim').length).toBeGreaterThan(500);
    expect(of('sentinelTop').length).toBe(4);
    expect(of('sentinelAbove').length).toBeGreaterThan(40);
    expect(of('live').length).toBe(24);
    expect(of('liveNext').length).toBe(96);
    expect(of('exitNames').length).toBe(8);
    expect(of('entrance').length).toBe(60);
  });

  it('keyframe endpoints equal the Lean values', () => {
    for (const r of of('keyframes')) {
      const k = keyframes(r.in.consumer as ConsumerName, r.in.le600 as boolean);
      const out = r.out as { from: unknown; to: unknown };
      expect(k.from).toBeCloseTo(q(out.from), 12);
      expect(k.to).toBeCloseTo(q(out.to), 12);
    }
  });

  it('the animated value equals the original value at every sampled scroll offset (consumer_eq_s)', () => {
    for (const r of of('anim')) {
      const { consumer, le600, T, h, v, y } = r.in as Record<string, number | string | boolean>;
      const out = r.out as { anim: unknown; orig: unknown };
      const args = [consumer as ConsumerName, le600 as boolean, T as number, h as number, v as number, y as number] as const;
      expect(animatedValue(...args)).toBeCloseTo(q(out.anim), 9);
      expect(originalValue(...args)).toBeCloseTo(q(out.orig), 9);
      expect(animatedValue(...args)).toBeCloseTo(originalValue(...args), 9);
    }
  });

  it('the sentinel sits at 19/20 of the exit range', () => {
    for (const r of of('sentinelTop')) expect(sentinelTop(r.in.h as number, r.in.v as number)).toBeCloseTo(q(r.out), 9);
  });

  it('the sentinel decides the pointer cut-off the original uses', () => {
    for (const r of of('sentinelAbove')) {
      const { T, h, v, y } = r.in as Record<string, number>;
      // the sentinel's top edge in viewport coordinates is T + sentinelTop - y; it has left through the top when negative
      expect(T! + sentinelTop(h!, v!) - y! < 0).toBe(r.out);
    }
  });

  it('the hand-over rule (one theorem per branch in Lean)', () => {
    for (const r of of('live')) {
      expect(threadedLive(r.in.splash as Splash, r.in.entranceFinished as boolean, r.in.supported as boolean, r.in.reduced as boolean)).toBe(r.out);
    }
  });

  it('the latched hand-over rule (liveNext)', () => {
    for (const r of of('liveNext')) {
      const i = r.in as Record<string, boolean | string>;
      expect(liveNext(i.prev as boolean, i.left as boolean, i.splash as Splash, i.entranceFinished as boolean, i.supported as boolean, i.reduced as boolean)).toBe(r.out);
    }
  });

  it('every consumer name of the golden is known', () => {
    for (const r of of('keyframes')) expect(CONSUMERS).toContain(r.in.consumer);
  });
});

describe('pointer cut-off from an observer entry', () => {
  it('is off only after the sentinel left through the top', () => {
    expect(pointerNoneFromEntry({ isIntersecting: false, boundingClientRect: { top: -1 } })).toBe(true);
    expect(pointerNoneFromEntry({ isIntersecting: true, boundingClientRect: { top: -0.5 } })).toBe(false);
    expect(pointerNoneFromEntry({ isIntersecting: false, boundingClientRect: { top: 500 } })).toBe(false);
  });
});

describe('threaded.module.css restates the Lean endpoints and conditions', () => {
  const css = readFileSync(resolve(__dirname, 'threaded.module.css'), 'utf8');
  const frames = new Map<string, Record<string, string>>();
  for (const m of css.matchAll(/@keyframes\s+(\w+)\s*\{\s*from\s*\{([^}]*)\}\s*to\s*\{([^}]*)\}/g)) {
    const decl = (s: string) => s.trim().replace(/;$/, '').replace(/\s+/g, ' ');
    frames.set(m[1]!, { from: decl(m[2]!), to: decl(m[3]!) });
  }
  const px = (n: number) => `${n}px`;

  it('conditions are byte-equal to the generated ones', () => {
    const found = [...css.matchAll(/@media\s+([^{]+)\{/g)].map((m) => m[1]!.trim().replace(/\s+/g, ' '));
    expect(found).toEqual([mediaCondition('mq.rm-nopref'), mediaCondition('mq.w-gt-600'), mediaCondition('mq.w-le-600')]);
  });

  it('opacity, blur and translate keyframes equal keyframes()', () => {
    const op = keyframes('copyOpacity', false);
    expect(frames.get('exitFade')).toEqual({ from: `opacity: ${op.from}`, to: `opacity: ${op.to}` });
    const co = keyframes('cardOpacity', false);
    expect(frames.get('exitCardFade')).toEqual({ from: `opacity: ${co.from}`, to: `opacity: ${co.to}` });
    const bl = keyframes('copyBlur', false);
    expect(keyframes('cueBlur', false)).toEqual(bl);
    expect(keyframes('cueBlur', true)).toEqual(bl);
    expect(frames.get('exitBlur')).toEqual({ from: `filter: blur(${px(bl.from)})`, to: `filter: blur(${px(bl.to)})` });
    const up = keyframes('copyTranslateY', false);
    expect(frames.get('exitCopyUp')).toEqual({ from: `transform: translateY(${px(up.from)})`, to: `transform: translateY(${px(up.to)})` });
    const upN = keyframes('copyTranslateY', true);
    expect(frames.get('exitCopyUpNarrow')).toEqual({
      from: `transform: translate(-50%, ${px(upN.from)})`,
      to: `transform: translate(-50%, ${px(upN.to)})`,
    });
    const cue = keyframes('cueTranslateY', true);
    expect(frames.get('exitCueUpNarrow')).toEqual({
      from: `transform: translate(-50%, ${px(cue.from)})`,
      to: `transform: translate(-50%, ${px(cue.to)})`,
    });
    // desktop cue does not move (Lean cueTranslateY false = 0 to 0), and the phone copy has no blur
    expect(keyframes('cueTranslateY', false)).toEqual({ from: 0, to: 0 });
    expect(keyframes('copyBlur', true)).toEqual({ from: 0, to: 0 });
    // the card moves by exactly its scatter vector: 0 to 1 times var(--scatter-x/y)
    expect(keyframes('cardTranslate', false)).toEqual({ from: 0, to: 1 });
    // read with the card's own entrance state (Lean cardTranslate entered enter off): `entered = 1` makes `from` 0 and `to` the scatter vector
    const m = frames.get('exitCardMove')!;
    expect(m.from).toBe('translate: calc((1 - var(--entered)) * var(--orbit-enter-x)) calc((1 - var(--entered)) * var(--orbit-enter-y))');
    expect(m.to).toBe(
      'translate: calc((1 - var(--entered)) * var(--orbit-enter-x) + var(--scatter-x)) calc((1 - var(--entered)) * var(--orbit-enter-y) + var(--scatter-y))',
    );
  });

  it('desktop copy and cue blur only in the wide band; phone copy has no blur animation', () => {
    const block = (sel: string, band: 'gt' | 'le') => {
      const media = band === 'gt' ? mediaCondition('mq.w-gt-600') : mediaCondition('mq.w-le-600');
      const start = css.indexOf(`@media ${media}`);
      const end = band === 'gt' ? css.indexOf(`@media ${mediaCondition('mq.w-le-600')}`) : css.indexOf('@keyframes');
      const body = css.slice(start, end);
      const at = body.indexOf(sel);
      return body.slice(at, body.indexOf('}', at));
    };
    expect(block("[data-fw-layer='hero_copy'] {", 'gt')).toContain('animation-name: exitFade, exitCopyUp, exitBlur;');
    expect(block("[data-fw-layer='hero.cue_cue'] {", 'gt')).toContain('animation-name: exitFade, exitBlur;');
    expect(block("[data-fw-layer='hero_copy'] {", 'le')).toContain('animation-name: exitFade, exitCopyUpNarrow;');
    expect(block("[data-fw-layer='hero.cue_cue'] {", 'le')).toContain('animation-name: exitFade, exitCueUpNarrow, exitBlur;');
  });

  it('every animation rule reads the track timeline over the contain range, linear, filled both ways', () => {
    const rules = [...css.matchAll(/animation-name:[^}]*\}/g)].map((m) => m[0]).filter((r) => r.includes('animation-timeline'));
    expect(rules.length).toBe(6);
    for (const r of rules) {
      expect(r).toMatch(/animation-timeline: --hero-exit;/);
      expect(r).toMatch(/animation-range: contain;/);
      expect(r).toMatch(/animation-timing-function: linear;/);
      expect(r).toMatch(/animation-fill-mode: both;/);
    }
    expect(css).toContain('view-timeline: --hero-exit block;');
  });

  it('the sentinel has no height, so the observer cuts pointer events exactly at the golden offset', () => {
    expect(css).toMatch(/\.sentinel \{[^}]*height: 0;/);
  });

  it('no rule names an animation on a card, hero copy or cue outside the live selector, and the live names are the golden exit names', () => {
    const body = css.slice(0, css.indexOf('@keyframes'));
    const selectors: Record<string, string> = {
      orbit: "[data-fw-layer='hero.orbit_card']",
      deck: "[data-fw-layer='hero.deck_article']",
      copy: "[data-fw-layer='hero_copy']",
      cue: "[data-fw-layer='hero.cue_cue']",
    };
    const rules = [...body.matchAll(/([^{}]+)\{([^{}]*animation-name:[^{}]*)\}/g)].map((m) => ({ sel: m[1]!.trim(), decl: m[2]! }));
    for (const r of rules) expect(r.sel).toMatch(/\[data-exit-live\] \[data-splash='done'\]/);
    const names = (decl: string) => /animation-name: ([^;]*);/.exec(decl)![1]!.split(', ');
    const section = (n: string, le600: boolean) => {
      const band = le600 ? mediaCondition('mq.w-le-600') : mediaCondition('mq.w-gt-600');
      const sel = selectors[n]!;
      const inBand = n === 'copy' || n === 'cue';
      const from = inBand ? css.indexOf(`@media ${band}`) : 0;
      const to = inBand && !le600 ? css.indexOf(`@media ${mediaCondition('mq.w-le-600')}`) : css.indexOf('@keyframes');
      const text = css.slice(from, to);
      const hits = rules.filter((r) => r.sel.endsWith(sel) && text.includes(r.decl));
      expect(hits.length).toBe(1);
      return names(hits[0]!.decl);
    };
    for (const r of of('exitNames')) {
      expect(section(r.in.node as string, r.in.le600 as boolean)).toEqual(r.out);
    }
    for (const sel of Object.values(selectors)) {
      const bare = rules.filter((r) => r.sel.endsWith(sel)).length;
      expect(bare).toBeGreaterThan(0);
    }
    expect(css).not.toContain('fwEntrance');
    expect(css).toContain("[data-fw='hero-exit'][data-exit-live] [data-splash='done'] [data-fw-layer='hero.orbit_card'] {");
  });

  it('the entrance rows: the variant minus the exit names is the original, with the same restarts', () => {
    const exits = new Map(of('exitNames').map((r) => [`${r.in.node}/${r.in.le600}`, r.out as string[]]));
    for (const r of of('entrance')) {
      const out = r.out as { orig: string[]; variant: string[]; origRestart: string[]; variantRestart: string[] };
      const drop = (l: string[]) => l.filter((x) => !exits.get(`${r.in.node}/${r.in.le600}`)!.includes(x));
      expect(drop(out.variant)).toEqual(out.orig);
      expect(drop(out.variantRestart)).toEqual(out.origRestart);
    }
  });
});

describe('hand-over controller', () => {
  function make(splash: Splash, opts: { supported?: boolean; reduced?: boolean; finished?: boolean } = {}) {
    const log: string[] = [];
    const stage = {
      attrs: { 'data-splash': splash as string },
      props: new Map<string, string>([['--exit-opacity', '0.4']]),
      style: {
        pointerEvents: 'none',
        removeProperty(n: string) {
          log.push(`remove ${n}`);
          return '';
        },
      },
      getAttribute(n: string) {
        return (this.attrs as Record<string, string>)[n] ?? null;
      },
    };
    const track = {
      attrs: new Set<string>(),
      setAttribute(n: string) {
        this.attrs.add(n);
      },
      removeAttribute(n: string) {
        this.attrs.delete(n);
      },
    };
    let reduced = opts.reduced ?? false;
    let finished = opts.finished ?? true;
    let report: (none: boolean) => void = () => {};
    let drivers = 0;
    let running = 0;
    const deps: HandoffDeps = {
      stage,
      track,
      supported: opts.supported ?? true,
      entranceFinished: () => finished,
      reduced: () => reduced,
      startDriver: () => {
        drivers++;
        running++;
        return () => {
          running--;
        };
      },
      placeSentinel: () => log.push('place'),
      watchSentinel: (cb) => {
        report = cb;
        log.push('watch');
        return () => log.push('unwatch');
      },
    };
    const h = createHandoff(deps);
    return {
      h,
      stage,
      track,
      log,
      drivers: () => drivers,
      running: () => running,
      report: (n: boolean) => report(n),
      setReduced: (r: boolean) => {
        reduced = r;
      },
      setFinished: (f: boolean) => {
        finished = f;
      },
    };
  }

  it('keeps the callback while the splash plays', () => {
    const a = make('run');
    expect(a.h.isLive()).toBe(false);
    expect(a.running()).toBe(1);
    expect(a.track.attrs.has(LIVE_ATTR)).toBe(false);
  });

  it('hands over at done: stops the callback, clears the inline opacity, lets the sentinel own pointer events', () => {
    const a = make('run');
    a.stage.attrs['data-splash'] = 'done';
    a.h.sync();
    expect(a.h.isLive()).toBe(true);
    expect(a.running()).toBe(0);
    expect(a.track.attrs.has(LIVE_ATTR)).toBe(true);
    expect(a.log).toEqual(['remove --exit-opacity', 'place', 'watch']);
    a.report(false);
    expect(a.stage.style.pointerEvents).toBe('');
    a.report(true);
    expect(a.stage.style.pointerEvents).toBe('none');
  });

  it('hands back on a [prep, run] batch at wide widths, before the next style pass', () => {
    const a = make('done');
    expect(a.h.isLive()).toBe(true);
    a.stage.attrs['data-splash'] = 'run';
    a.h.onMutations([{ oldValue: 'done' }, { oldValue: 'prep' }]);
    expect(a.h.isLive()).toBe(false);
    expect(a.track.attrs.has(LIVE_ATTR)).toBe(false);
    expect(a.running()).toBe(1);
    expect(a.drivers()).toBe(2);
    expect(a.stage.style.pointerEvents).toBe('');
    expect(a.log).toContain('unwatch');
  });

  it('hands back on a [prep, run, done] batch at phone widths while the cue plays, and is live again after animationend', () => {
    const a = make('done');
    a.setFinished(false);
    a.h.onMutations([{ oldValue: 'done' }, { oldValue: 'prep' }, { oldValue: 'run' }]);
    expect(a.h.isLive()).toBe(false);
    expect(a.track.attrs.has(LIVE_ATTR)).toBe(false);
    expect(a.running()).toBe(1);
    a.setFinished(true);
    a.h.sync();
    expect(a.h.isLive()).toBe(true);
    expect(a.track.attrs.has(LIVE_ATTR)).toBe(true);
  });

  it('a batch that never saw done keeps the latch', () => {
    const a = make('done');
    a.setFinished(false);
    a.h.onMutations([{ oldValue: 'run' }]);
    expect(a.h.isLive()).toBe(true);
  });

  it('keeps the callback at splash done while an entrance animation still runs, and hands over when it ends', () => {
    const a = make('done', { finished: false });
    expect(a.h.isLive()).toBe(false);
    expect(a.running()).toBe(1);
    expect(a.track.attrs.has(LIVE_ATTR)).toBe(false);
    a.setFinished(true);
    a.h.sync();
    expect(a.h.isLive()).toBe(true);
    expect(a.running()).toBe(0);
  });

  it('stays live when the live animations themselves make the entrance read as unfinished', () => {
    const a = make('done');
    a.setFinished(false);
    a.h.sync();
    expect(a.h.isLive()).toBe(true);
  });

  it('never hands over without animation-timeline support or under reduced motion', () => {
    const a = make('done', { supported: false });
    expect(a.h.isLive()).toBe(false);
    expect(a.running()).toBe(1);
    const b = make('done', { reduced: true });
    expect(b.h.isLive()).toBe(false);
    b.setReduced(false);
    b.h.sync();
    expect(b.h.isLive()).toBe(true);
    b.setReduced(true);
    b.h.sync();
    expect(b.h.isLive()).toBe(false);
  });

  it('does nothing between changes and moves the sentinel on resize only while live', () => {
    const a = make('done');
    const n = a.log.length;
    a.h.sync();
    a.h.sync();
    expect(a.log.length).toBe(n);
    a.h.resize();
    expect(a.log[a.log.length - 1]).toBe('place');
    const b = make('run');
    b.h.resize();
    expect(b.log).toEqual([]);
  });

  it('stop leaves nothing running or attached', () => {
    const a = make('done');
    a.h.stop();
    expect(a.running()).toBe(0);
    expect(a.track.attrs.size).toBe(0);
    const b = make('run');
    b.h.stop();
    expect(b.running()).toBe(0);
  });
});
